import os
import re
from typing import Any, Dict, List, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


REQUIRED_FIELDS = [
    "vendor_name",
    "invoice_id",
    "invoice_date",
    "total_amount",
    "currency",
]


def _field_value_to_text(field: Any) -> Optional[str]:
    if field is None:
        return None
    if isinstance(field, str):
        return field.strip() or None
    value = getattr(field, "value", None)
    if value is not None:
        if isinstance(value, str):
            return value.strip() or None
        return str(value).strip() or None
    content = getattr(field, "content", None)
    if content is not None:
        return str(content).strip() or None
    if isinstance(field, (int, float, bool)):
        return str(field)
    return str(field).strip() or None


def _field_confidence(field: Any) -> Optional[float]:
    if field is None:
        return None
    confidence = getattr(field, "confidence", None)
    if confidence is None:
        return None
    try:
        return float(confidence)
    except (TypeError, ValueError):
        return None


def _normalize_document_fields(doc: Any) -> Dict[str, Dict[str, Any]]:
    fields = getattr(doc, "fields", {}) or {}
    normalized: Dict[str, Dict[str, Any]] = {}

    for key, field in fields.items():
        normalized[key] = {
            "value": _field_value_to_text(field),
            "confidence": _field_confidence(field),
        }

    return normalized


def _best_match_field(fields: Dict[str, Dict[str, Any]], aliases: List[str]) -> Optional[Dict[str, Any]]:
    lowered = {k.lower(): v for k, v in fields.items()}
    for alias in aliases:
        if alias.lower() in lowered:
            return lowered[alias.lower()]
    for key, val in lowered.items():
        if any(alias.lower() in key for alias in aliases):
            return val
    return None


def _validate_required_fields(fields: Dict[str, Dict[str, Any]], min_confidence: float) -> List[str]:
    errors: List[str] = []

    alias_map = {
        "vendor_name": ["VendorName", "MerchantName", "SupplierName", "Vendor", "Merchant"],
        "invoice_id": ["InvoiceId", "InvoiceNumber", "DocumentNumber", "InvoiceNo", "Invoice"],
        "invoice_date": ["InvoiceDate", "IssueDate", "TransactionDate", "Date"],
        "total_amount": ["Total", "InvoiceTotal", "AmountDue", "TotalAmount", "GrandTotal"],
        "currency": ["Currency", "TransactionCurrency"],
    }

    for required in REQUIRED_FIELDS:
        match = _best_match_field(fields, alias_map[required])
        if match is None or match.get("value") in (None, ""):
            errors.append(f"Missing required field: {required}")
            continue

        conf = match.get("confidence")
        if conf is None:
            errors.append(f"Missing confidence for required field: {required}")
        elif conf < min_confidence:
            errors.append(
                f"Low confidence for required field: {required} (confidence={conf:.3f}, minimum={min_confidence:.3f})"
            )

    return errors


def extract_and_validate_invoice(
    document_path: str,
    model_id: str = "prebuilt-invoice",
    min_confidence: float = 0.80,
) -> Dict[str, Any]:
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    with open(document_path, "rb") as f:
        poller = client.begin_analyze_document(model_id=model_id, body=f)
        result = poller.result()

    documents = getattr(result, "documents", []) or []
    if not documents:
        return {
            "valid": False,
            "errors": ["No invoice document detected"],
            "fields": {},
        }

    doc = documents[0]
    fields = _normalize_document_fields(doc)
    errors = _validate_required_fields(fields, min_confidence=min_confidence)

    return {
        "valid": len(errors) == 0,
        "errors": errors,
        "fields": fields,
    }
